using System;using System.IO;using System.Linq;using System.Collections.Generic;using Musikbox;
class OfflineSpeechAudioTests {
 static void Main(string[] args){var phrases=new List<string>();using(var speech=new OfflineSpeech(new[]{Path.Combine(args[0],"de"),Path.Combine(args[0],"en")})){byte[] audio=File.ReadAllBytes(args[1]);for(int i=0;i<audio.Length;i+=3200){int n=Math.Min(3200,audio.Length-i);byte[] chunk=new byte[n];Array.Copy(audio,i,chunk,0,n);phrases.AddRange(speech.Feed(chunk,n));}phrases.AddRange(speech.Finish());}Console.WriteLine("Erkannt: "+String.Join(" | ",phrases));var song=new Song{Artist="Glen Campbell",Title="Sunflower",Album="Country",Source="test.mp3"};string query=LibrarySearch.VoiceQuery(new[]{song},phrases);Console.WriteLine("Suchbegriff: "+query);if(!query.ToLowerInvariant().Contains("sunflower")||!query.ToLowerInvariant().Contains("campbell"))throw new Exception("Synthetische englische Testaufnahme nicht zugeordnet");Console.WriteLine("BESTANDEN: echte PCM-Verarbeitung mit beiden Offline-Modellen und synthetischer englischer Stimme. Kein Windows-Mikrofontest.");}
}
